ALTER TABLE "User" ADD COLUMN "batch" INTEGER NOT NULL DEFAULT 2025, ADD COLUMN "privateProfile" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "TimetableEntry" ADD COLUMN "cancelled" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Notification" ADD COLUMN "dispatchedAt" TIMESTAMP(3);
ALTER TABLE "OAuthState" ADD COLUMN "mobileRedirect" TEXT, ADD COLUMN "mobileChallenge" TEXT, ADD COLUMN "mobileState" TEXT;
CREATE TABLE "MobileLogin" ("codeHash" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"challenge" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MobileLogin_expiresAt_idx" ON "MobileLogin"("expiresAt");
CREATE TABLE "PushPreference" ("userId" TEXT PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"settings" JSONB NOT NULL);
CREATE TABLE "PushDevice" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"tokenHash" TEXT NOT NULL,"sealedToken" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"platform" TEXT NOT NULL);
CREATE UNIQUE INDEX "PushDevice_tokenHash_key" ON "PushDevice"("tokenHash");
CREATE TABLE "PushDelivery" ("id" TEXT PRIMARY KEY,"notificationId" TEXT NOT NULL REFERENCES "Notification"("id") ON DELETE CASCADE ON UPDATE CASCADE,"deviceId" TEXT NOT NULL REFERENCES "PushDevice"("id") ON DELETE CASCADE ON UPDATE CASCADE,"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leasedAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"receiptId" TEXT,"error" TEXT);
CREATE UNIQUE INDEX "PushDelivery_notificationId_deviceId_key" ON "PushDelivery"("notificationId","deviceId");
CREATE INDEX "PushDelivery_deliveredAt_availableAt_idx" ON "PushDelivery"("deliveredAt","availableAt");
CREATE TABLE "TimetableSnapshot" ("id" TEXT PRIMARY KEY,"branch" TEXT NOT NULL,"semester" INTEGER NOT NULL,"section" TEXT NOT NULL,"version" INTEGER NOT NULL,"hash" TEXT NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "TimetableSnapshot_branch_semester_section_version_key" ON "TimetableSnapshot"("branch","semester","section","version");
CREATE TABLE "ReplyVote" ("replyId" TEXT NOT NULL REFERENCES "DiscussionReply"("id") ON DELETE CASCADE ON UPDATE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ReplyVote_pkey" PRIMARY KEY("replyId","userId"));
CREATE TABLE "DiscussionBookmark" ("discussionId" TEXT NOT NULL REFERENCES "Discussion"("id") ON DELETE CASCADE ON UPDATE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "DiscussionBookmark_pkey" PRIMARY KEY("discussionId","userId"));
CREATE TABLE "ContentReport" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,"targetId" TEXT NOT NULL,"type" TEXT NOT NULL,"reason" TEXT NOT NULL,"resolved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "ContentReport_userId_targetId_type_key" ON "ContentReport"("userId","targetId","type");
CREATE INDEX "ContentReport_resolved_createdAt_idx" ON "ContentReport"("resolved","createdAt");
